4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.springframework.dao.DuplicateKeyException;
6	import org.springframework.stereotype.Service;
7	import org.springframework.transaction.annotation.Transactional;
8	
9	import java.util.function.Supplier;
10	
11	/**
12	 * 幂等执行器：指纹覆盖 requestId 与全部业务字段。
13	 *
14	 * <p>裁决方式：先以 requestId 主键插入“占位记录”（与业务在同一事务），
15	 * 并发同键请求会在唯一索引上阻塞并拿到 DuplicateKeyException，从而被串行裁决；
16	 * 业务全部完成后于同事务回写首次结果。同键同参返回首次结果（replay=true）；
17	 * 同键异参抛 {@link IdempotentConflictException}（409），此路径不执行任何业务写入。
18	 */
19	@Service
20	public class IdempotencyService {
21	
22	    private static final String PLACEHOLDER = "";
23	
24	    private final IdempotentRecordRepository repository;
25	    private final FingerprintUtil fingerprintUtil;
26	    private final ObjectMapper objectMapper;
27	
28	    public IdempotencyService(IdempotentRecordRepository repository,
29	                              FingerprintUtil fingerprintUtil,
30	                              ObjectMapper objectMapper) {
31	        this.repository = repository;
32	        this.fingerprintUtil = fingerprintUtil;
33	        this.objectMapper = objectMapper;
34	    }
35	
36	    @Transactional
37	    public <T> ReplayResult<T> run(String requestId, Long stationId, String apiType,
38	                                   Object payload, int httpStatus, Supplier<T> action,
39	                                   Class<T> resultType) {
40	        String fingerprint = fingerprintUtil.fingerprint(requestId, payload);
41	
42	        IdempotentRecord existing = repository.find(requestId).orElse(null);
43	        if (existing == null) {
44	            try {
45	                repository.insert(new IdempotentRecord(requestId, stationId, apiType,
46	                        fingerprint, httpStatus, PLACEHOLDER, null));
47	            } catch (DuplicateKeyException concurrent) {
48	                // 同键并发请求已先占位，按已落库的首次记录裁决
49	                existing = waitForCompleted(requestId);
50	                return resolveExisting(existing, fingerprint, resultType);
51	            }
52	            T result = action.get();
53	            repository.updateResult(requestId, httpStatus, toJson(result));
54	            return new ReplayResult<>(result, false, httpStatus);
55	        }
56	        return resolveExisting(existing, fingerprint, resultType);
57	    }
58	
59	    @SuppressWarnings("unchecked")
60	    private <T> ReplayResult<T> resolveExisting(IdempotentRecord existing, String fingerprint,
61	                                                Class<T> resultType) {
62	        if (!existing.fingerprint().equals(fingerprint)) {
63	            // 同键异参：409，不触发任何业务逻辑、不改变阀门状态
64	            throw new IdempotentConflictException(existing.requestId());
65	        }
66	        T firstResult = (T) fromJson(existing.resultJson(), resultType);
67	        if (firstResult instanceof Replayable<?> replayable) {
68	            firstResult = (T) replayable.withReplay(true);
69	        }
70	        return new ReplayResult<>(firstResult, true, existing.httpStatus());
71	    }
72	
73	    /**
74	     * 防御性等待：理论上占位与回写同事务提交，重查时必为完成态；此处仅兜底极端可见性场景。
75	     */
76	    private IdempotentRecord waitForCompleted(String requestId) {
77	        for (int i = 0; i < 50; i++) {
78	            IdempotentRecord record = repository.find(requestId)
79	                    .orElseThrow(() -> new IdempotentConflictException(requestId));
80	            if (!PLACEHOLDER.equals(record.resultJson())) {
81	                return record;
82	            }
83	            try {
84	                Thread.sleep(20);
85	            } catch (InterruptedException e) {
86	                Thread.currentThread().interrupt();
87	                throw new IdempotentConflictException(requestId);
88	            }
89	        }
90	        throw new IdempotentConflictException(requestId);
91	    }
