22	/**
23	 * 压力调节：分级判定与联动。
24	 *
25	 * <ul>
26	 *   <li>压力恰等于上/下限判 NORMAL 合格；低于下限 LOW、超上限 HIGH 触发联动；</li>
27	 *   <li>同一门站同一检测时刻仅允许一个执行中联动任务：先预检、再由
28	 *       linkage_task(station_id, detected_at) 唯一约束兜底，并发下达唯一受理，
29	 *       未受理方返回 409；</li>
30	 *   <li>PRESSURE 调压（回归目标压力）与 INJECTION 比例加注调整在同一事务下发，
31	 *       任一失败整体回滚；</li>
32	 *   <li>对应业务日期已封存时只落迟到事件，不联动。</li>
33	 * </ul>
34	 */
35	@Service
36	public class PressureService {
37	
38	    private final StationRepository stationRepository;
39	    private final ValveStateRepository valveStateRepository;
40	    private final PressureReadingRepository readingRepository;
41	    private final LateEventRepository lateEventRepository;
42	    private final DailyCloseRepository dailyCloseRepository;
43	    private final StationTaskLockRepository taskLockRepository;
44	    private final LinkageTaskRepository linkageTaskRepository;
45	    private final AdjustmentIssueRepository adjustmentIssueRepository;
46	    private final IdempotencyService idempotencyService;
