48	    public PressureService(StationRepository stationRepository,
49	                           ValveStateRepository valveStateRepository,
50	                           PressureReadingRepository readingRepository,
51	                           LateEventRepository lateEventRepository,
52	                           DailyCloseRepository dailyCloseRepository,
53	                           StationTaskLockRepository taskLockRepository,
54	                           LinkageTaskRepository linkageTaskRepository,
55	                           AdjustmentIssueRepository adjustmentIssueRepository,
56	                           IdempotencyService idempotencyService) {
57	        this.stationRepository = stationRepository;
58	        this.valveStateRepository = valveStateRepository;
59	        this.readingRepository = readingRepository;
60	        this.lateEventRepository = lateEventRepository;
61	        this.dailyCloseRepository = dailyCloseRepository;
62	        this.taskLockRepository = taskLockRepository;
63	        this.linkageTaskRepository = linkageTaskRepository;
64	        this.adjustmentIssueRepository = adjustmentIssueRepository;
65	        this.idempotencyService = idempotencyService;
66	    }
67	
68	    public PressureDetectResponse detect(PressureDetectRequest request) {
69	        Station station = stationRepository.findByCode(request.stationCode())
70	                .orElseThrow(() -> new ResourceNotFoundException(
71	                        "station not found: " + request.stationCode()));
72	        ReplayResult<PressureDetectResponse> replay = idempotencyService.run(
73	                request.requestId(), station.id(), "PRESSURE_DETECT", request, 200,
74	                () -> doDetect(station, request), PressureDetectResponse.class);
75	        return replay.result();
76	    }
77	
78	    private PressureDetectResponse doDetect(Station station, PressureDetectRequest request) {
79	        BigDecimal measured = request.pressureMpa();
80	        String grade = grade(station, measured);
81	        LocalDate bizDate = request.detectedAt().toLocalDate();
82	
83	        if (dailyCloseRepository.isSealed(station.id(), bizDate)) {
84	            // 封存终态：迟到压力检测只记事件，不触发联动
85	            lateEventRepository.insert(station.id(), "PRESSURE", request.requestId(),
86	                    request.detectedAt(), request);
87	            return new PressureDetectResponse(grade, false, null,
88	                    measured, measured, null, null, BigDecimal.ZERO, true, false);
89	        }
90	
91	        ValveState state = valveStateRepository.selectForUpdate(station.id());
92	
93	        if ("NORMAL".equals(grade)) {
94	            // 恰等限值或区间内：合格，无联动
95	            readingRepository.insert(station.id(), request.requestId(), request.detectedAt(),
96	                    measured, grade, null);
97	            return new PressureDetectResponse(grade, false, null,
98	                    measured, measured,
99	                    state.currentInjectionRateMgM3(), state.currentInjectionRateMgM3(),
100	                    BigDecimal.ZERO, false, false);
101	        }
102	
103	        if (taskLockRepository.existsAtSameInstant(station.id(), request.detectedAt())) {
104	            throw new TaskNotAcceptedException(
105	                    "linkage task already running for station at detectedAt=" + request.detectedAt());
106	        }
107	
108	        Long taskId;
109	        try {
110	            taskId = linkageTaskRepository.insertAccepted(station.id(), request.requestId(),
111	                    request.detectedAt(), measured, state.currentInjectionRateMgM3(),
112	                    request.gasFlowM3());
113	        } catch (DuplicateKeyException concurrent) {
114	            // 同刻并发：唯一约束裁决，仅首个请求受理
115	            throw new TaskNotAcceptedException(
116	                    "linkage task already running for station at detectedAt=" + request.detectedAt());
117	        }
118	
119	        BigDecimal targetPressure = station.pressureTargetMpa();
120	        BigDecimal rateBefore = state.currentInjectionRateMgM3();
121	        BigDecimal rateAfter;
122	        BigDecimal dose;
123	        if (state.injectionLocked()) {
124	            // 加注阀锁定中：加注指令以“维持、零加注量”下发，调压仍执行
125	            rateAfter = rateBefore;
126	            dose = BigDecimal.ZERO.setScale(3, RoundingMode.HALF_UP);
127	        } else {
128	            // 比例投加：联动后速率折算浓度回归目标浓度，本次加注量 = 流量 × 目标浓度
129	            rateAfter = station.targetConcentrationMgM3();
130	            dose = request.gasFlowM3()
131	                    .multiply(station.targetConcentrationMgM3())
132	                    .setScale(3, RoundingMode.HALF_UP);
133	        }
134	
135	        // 调压与加注调整同事务下发（两条指令 + 状态更新 + 任务完成原子提交）
136	        adjustmentIssueRepository.insert(taskId, station.id(), "PRESSURE", measured, targetPressure);
137	        adjustmentIssueRepository.insert(taskId, station.id(), "INJECTION", rateBefore, rateAfter);
138	        valveStateRepository.updateInjectionAndPressure(station.id(), rateAfter, targetPressure);
139	        linkageTaskRepository.complete(taskId, targetPressure, rateAfter, dose);
140	        readingRepository.insert(station.id(), request.requestId(), request.detectedAt(),
141	                measured, grade, taskId);
142	
143	        return new PressureDetectResponse(grade, true, taskId,
144	                measured, targetPressure, rateBefore, rateAfter, dose, false, false);
145	    }
146	
147	    private String grade(Station station, BigDecimal measured) {
148	        // 闭区间：恰等于 0.3000 / 0.5000 均判合格
149	        if (measured.compareTo(station.pressureLowLimitMpa()) < 0) {
150	            return "LOW";
151	        }
152	        if (measured.compareTo(station.pressureHighLimitMpa()) > 0) {
153	            return "HIGH";
154	        }
155	        return "NORMAL";
156	    }
157	}
