64	                            BigDecimal injectionRateMgM3, BigDecimal pressureMpa) {
65	        jdbc.update("""
66	                        UPDATE valve_state
67	                        SET injection_locked = ?, alarm_active = ?, breach_count = ?,
68	                            current_injection_rate_mg_m3 = ?, current_pressure_mpa = ?,
69	                            updated_at = CURRENT_TIMESTAMP
70	                        WHERE station_id = ?
71	                        """,
72	                locked, alarm, breachCount, injectionRateMgM3, pressureMpa, stationId);
73	    }
74	
75	    /**
76	     * 仅更新加注速率与压力（压力联动使用），锁阀/告警/越限计数保持不变。
77	     */
78	    public void updateInjectionAndPressure(Long stationId, BigDecimal injectionRateMgM3,
79	                                           BigDecimal pressureMpa) {
80	        jdbc.update("""
81	                        UPDATE valve_state
82	                        SET current_injection_rate_mg_m3 = ?, current_pressure_mpa = ?,
83	                            updated_at = CURRENT_TIMESTAMP
84	                        WHERE station_id = ?
85	                        """,
86	                injectionRateMgM3, pressureMpa, stationId);
87	    }
88	}
