12	
13	import java.math.BigDecimal;
14	import java.math.RoundingMode;
15	import java.time.LocalDate;
16	
17	/**
18	 * 日结：加臭剂消耗与累计流量勾稽，恰 3% 合格封存，超差转人工。
19	 *
20	 * <ul>
21	 *   <li>理论消耗 = 当日有效检测累计流量 × 目标浓度（20mg/m³）；</li>
22	 *   <li>偏差 = |实际上报 − 理论| / 理论 × 100%；偏差 ≤ 3.00%（闭区间，恰 3% 合格）
23	 *       且无 MANUAL 未处理时封存为终态 SEALED；超过 3% 转人工 MANUAL；</li>
24	 *   <li>已封存（终态）：重复封存同参返回幂等成功，不重新计算、不改数据；
25	 *       同键异参 409（由幂等层保证）且不改阀门状态；</li>
26	 *   <li>MANUAL 状态下再次日结（不同 requestId、新数据）允许重新勾稽，达标后封存。</li>
27	 * </ul>
28	 */
29	@Service
30	public class DailyCloseService {
31	
32	    private static final BigDecimal ALLOWED_DEVIATION_PCT = new BigDecimal("3.0000");
33	    private static final int DEVIATION_SCALE = 4;
34	
35	    private final StationRepository stationRepository;
36	    private final OdorantReadingRepository readingRepository;
37	    private final DailyCloseRepository dailyCloseRepository;
38	    private final IdempotencyService idempotencyService;
39	
40	    public DailyCloseService(StationRepository stationRepository,
41	                             OdorantReadingRepository readingRepository,
42	                             DailyCloseRepository dailyCloseRepository,
43	                             IdempotencyService idempotencyService) {
44	        this.stationRepository = stationRepository;
45	        this.readingRepository = readingRepository;
46	        this.dailyCloseRepository = dailyCloseRepository;
47	        this.idempotencyService = idempotencyService;
48	    }
49	
50	    public DailyCloseResponse close(DailyCloseRequest request) {
51	        Station station = stationRepository.findByCode(request.stationCode())
52	                .orElseThrow(() -> new ResourceNotFoundException(
53	                        "station not found: " + request.stationCode()));
54	        ReplayResult<DailyCloseResponse> retry = idempotencyService.run(
55	                request.requestId(), station.id(), "DAILY_CLOSE", request, 200,
56	                () -> doClose(station, request), DailyCloseResponse.class);
57	        return retry.result();
58	    }
59	
60	    private DailyCloseResponse toResponse(DailyCloseRow row, boolean replay) {
61	        return new DailyCloseResponse(row.bizDate(), row.status(), row.totalFlowM3(),
62	                row.expectedOdorantMg(), row.reportedOdorantMg(), row.deviationPct(),
63	                "SEALED".equals(row.status()), row.sealedAt(), replay);
64	    }
65	
66	    private DailyCloseResponse doClose(Station station, DailyCloseRequest request) {
67	        LocalDate bizDate = request.bizDate();
68	
69	        DailyCloseRow existing = dailyCloseRepository.findForUpdate(station.id(), bizDate).orElse(null);
70	        if (existing != null && "SEALED".equals(existing.status())) {
71	            // 封存为终态：重复封存返回首次封存结果（新请求同参的重放由幂等层标记 replay）
72	            return toResponse(existing, false);
73	        }
74	
75	        BigDecimal totalFlow = readingRepository.sumFlowByDate(station.id(), bizDate);
76	        BigDecimal expected = totalFlow.multiply(station.targetConcentrationMgM3())
77	                .setScale(3, RoundingMode.HALF_UP);
78	        BigDecimal reported = request.reportedOdorantMg().setScale(3, RoundingMode.HALF_UP);
79	        BigDecimal deviation;
80	        if (expected.compareTo(BigDecimal.ZERO) == 0) {
81	            // 当日无检测流量：理论消耗为 0，仅当实际上报也为 0 时偏差 0%
82	            deviation = reported.compareTo(BigDecimal.ZERO) == 0
83	                    ? BigDecimal.ZERO.setScale(DEVIATION_SCALE, RoundingMode.HALF_UP)
84	                    : new BigDecimal("100.0000");
85	        } else {
86	            deviation = reported.subtract(expected).abs()
87	                    .multiply(BigDecimal.valueOf(100))
88	                    .divide(expected, DEVIATION_SCALE, RoundingMode.HALF_UP);
89	        }
90	
91	        boolean sealed = deviation.compareTo(ALLOWED_DEVIATION_PCT) <= 0;
92	        String status = sealed ? "SEALED" : "MANUAL";
93	
94	        if (existing == null) {
95	            try {
96	                dailyCloseRepository.insert(station.id(), bizDate, status, totalFlow, expected,
97	                        reported, deviation, sealed ? request.requestId() : null, sealed);
98	            } catch (org.springframework.dao.DuplicateKeyException concurrent) {
99	                // 不同 requestId 并发日结同一日：唯一约束裁决，回查首个落库结果
100	                DailyCloseRow winner = dailyCloseRepository.findForUpdate(station.id(), bizDate)
101	                        .orElseThrow();
102	                return toResponse(winner, false);
103	            }
104	        } else {
105	            // MANUAL → 达标封存 / 仍超差保持转人工
106	            dailyCloseRepository.update(station.id(), bizDate, status, reported, deviation,
107	                    sealed ? request.requestId() : null, sealed);
108	        }
109	
110	        DailyCloseRow saved = dailyCloseRepository.findForUpdate(station.id(), bizDate).orElseThrow();
111	        return toResponse(saved, false);
112	    }
113	}
