2	
3	import com.example.starter.AbstractIntegrationTest;
4	import com.example.starter.web.dto.OdorantDetectRequest;
5	import com.example.starter.web.dto.OdorantDetectResponse;
6	import org.junit.jupiter.api.Test;
7	import org.springframework.beans.factory.annotation.Autowired;
8	
9	import java.math.BigDecimal;
10	import java.time.LocalDate;
11	import java.time.LocalDateTime;
12	import java.util.concurrent.CountDownLatch;
13	import java.util.concurrent.ExecutorService;
14	import java.util.concurrent.Executors;
15	import java.util.concurrent.Future;
16	import java.util.concurrent.TimeUnit;
17	
18	import static org.junit.jupiter.api.Assertions.assertEquals;
19	import static org.junit.jupiter.api.Assertions.assertTrue;
20	
21	/**
22	 * 浓度越限并发边界：同一时刻两个不同 requestId 并发上报越限，
23	 * 经 valve_state 行锁串行计数，恰一个请求触发锁阀，不允许重复锁/重复工单。
24	 */
25	class OdorantConcurrencyTest extends AbstractIntegrationTest {
26	
27	    private static final LocalDateTime T = LocalDate.of(2026, 9, 25).atTime(12, 0);
28	
29	    @Autowired
30	    private OdorantService odorantService;
31	
32	    @Test
33	    @SuppressWarnings("unchecked")
34	    void concurrentBreachReportsLockExactlyOnce() throws Exception {
35	        int threads = 2;
36	        ExecutorService pool = Executors.newFixedThreadPool(threads);
37	        CountDownLatch start = new CountDownLatch(1);
38	        Future<OdorantDetectResponse>[] futures = new Future[threads];
39	        for (int i = 0; i < threads; i++) {
40	            final int idx = i;
41	            futures[i] = pool.submit(() -> {
42	                start.await();
43	                return odorantService.detect(new OdorantDetectRequest("ST01", "OC-" + idx,
44	                        T.plusMinutes(idx), new BigDecimal("100"), new BigDecimal("15.000")));
45	            });
46	        }
47	        start.countDown();
48	
49	        int locks = 0;
50	        int maxBreach = 0;
51	        for (Future<OdorantDetectResponse> f : futures) {
52	            OdorantDetectResponse resp = f.get(15, TimeUnit.SECONDS);
53	            if (resp.injectionLocked()) {
54	                locks++;
55	            }
56	            maxBreach = Math.max(maxBreach, resp.breachCount());
57	        }
58	        pool.shutdown();
59	
60	        assertEquals(1, locks, "并发越限只允许恰一个请求锁阀");
61	        assertEquals(2, maxBreach, "行锁串行后连续越限计数必须达到2");
62	        assertEquals(1, count("SELECT COUNT(*) FROM lock_order WHERE station_id = 1 AND action = 'LOCK' "
63	                + "AND status = 'PENDING' AND trigger_request_id IS NOT NULL"), "触发锁阀单恰一张");
64	        assertTrue(queryBoolean("SELECT injection_locked FROM valve_state WHERE station_id = 1"));
65	    }
66	
67	    private boolean queryBoolean(String sql) {
68	        return Boolean.TRUE.equals(jdbc.queryForObject(sql, Boolean.class));
69	    }
70	}
