        if (reserve != null && !reserve.dispatched()) {
            // 储备不足：已生成待补液事件，不下发加注；调压仍执行，不伪报加注成功
            rateAfter = rateBefore;
            dose = BigDecimal.ZERO.setScale(3, RoundingMode.HALF_UP);
        }
    }
}

